static const struct { const char *name; LayoutTerrain terrain; } terrains[] = {
    {"Arena2", {arena2_trench_vertices, sizeof(arena2_trench_vertices)/sizeof(*arena2_trench_vertices), arena2_trench_triangles, sizeof(arena2_trench_triangles)/sizeof(*arena2_trench_triangles)}},
    {"ctf_Ash", {ash_fort_vertices, sizeof(ash_fort_vertices)/sizeof(*ash_fort_vertices), ash_fort_triangles, sizeof(ash_fort_triangles)/sizeof(*ash_fort_triangles)}},
};

const LayoutTerrain *world_terrain_pilots(const char *name)
{
    for(size_t i=0;i<sizeof(terrains)/sizeof(*terrains);++i)
        if(strcmp(name,terrains[i].name)==0)return &terrains[i].terrain;
    return NULL;
}
